export function WeeklyWork({jobs,actor,onOpen,teamView=false}:{jobs:JobRecord[];actor:Actor;onOpen:(job:JobRecord,tab:string)=>void;teamView?:boolean}){
 const [showCompleted,setShowCompleted]=useState(false);
 const [week,setWeek]=useState(localDate()),[mode,setMode]=useState('list'),[search,setSearch]=useState('');const start=new Date(week+'T00:00:00Z');start.setUTCDate(start.getUTCDate()-((start.getUTCDay()+6)%7));const end=new Date(start);end.setUTCDate(end.getUTCDate()+6);const from=start.toISOString().slice(0,10),to=end.toISOString().slice(0,10);const today=new Date().toISOString().slice(0,10);
 const all=jobs.flatMap(job=>operationsFor(job).activities.map(a=>({job,a}))).filter(({a})=>teamView?actor.id==='MA001'||[holder(actor,'scopeSelector'),holder(actor,streamLead(a.stream)),a.stream==='PVT'?holder(actor,'pvtSupervisor'):''].filter(Boolean).includes(actor.id):a.owner===actor.id).filter(({job,a})=>[job.jobNumber,job.clientName,a.title,a.sampleId].join(' ').toLowerCase().includes(search.toLowerCase()));
 const work=all.filter(({a})=>(showCompleted||a.status!=='Completed')&&(!a.start||a.start<=to&&a.due>=from||a.status==='Changes Requested'||a.status!=='Completed'&&a.due<today));
 const pending=jobs.flatMap(job=>pendingActions(job,actor).map(m=>({job,m})));
 return <section className="panel ops-panel"><div className="panel-heading"><div><span className="eyebrow">{teamView?'TEAM PLANNING':'MY WORK'}</span><h2>{teamView?'Weekly laboratory plan':'Your week and next actions'}</h2><p>{from} — {to} · Dates include activities crossing week boundaries.</p></div></div><div className="settings-filters"><label>Week containing<input type="date" value={week} onChange={e=>{if(e.target.value)setWeek(e.target.value);}}/></label><label>Search<input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Job, activity or sample"/></label><label>Layout<select value={mode} onChange={e=>setMode(e.target.value)}><option value="list">Accessible list</option><option value="week">Weekly layout</option></select></label><label className="ops-check"><input type="checkbox" checked={showCompleted} onChange={e=>setShowCompleted(e.target.checked)}/>Include completed work</label></div>{!teamView&&pending.length>0&&<div className="ops-next-actions"><h3>Waiting for your action</h3>{pending.map(({job,m})=><button className="ops-task" key={job.id+m.id} onClick={()=>onOpen(job,m.id)}><strong>{job.jobNumber} · {job.clientName}</strong><span>{m.label}: {m.next}</span><small>Due {job.dueDate||'not set'}</small></button>)}</div>}{mode==='list'?<div className="ops-table-wrap"><table><thead><tr><th>Job / client</th><th>Activity / sample</th><th>Employee</th><th>Planned dates</th><th>Status / next action</th></tr></thead><tbody>{work.map(({job,a})=><tr key={job.id+a.id}><td>{job.jobNumber}<small>{job.clientName}</small></td><td>{a.title}<small>{a.stream} · Sample {a.sampleId}</small>{a.notes&&<small>{a.notes}</small>}</td><td>{actor.employees.find(e=>e.id===a.owner)?.name||'Unassigned'}</td><td>{a.start||'Unscheduled'} → {a.due||'No due date'}{a.due&&a.due<today&&a.status!=='Completed'&&<strong className="ops-overdue">Overdue</strong>}</td><td><button className="text-button" onClick={()=>onOpen(job,'laboratory?activity='+encodeURIComponent(a.id))}>{a.status} · {a.status==='Changes Requested'?'Correct workbook':a.status==='Completed'?'View record':a.files.length?'Review / complete':'Open activity'}</button></td></tr>)}</tbody></table></div>:<div className="ops-week">{Array.from({length:7},(_,i)=>{const d=new Date(start);d.setUTCDate(d.getUTCDate()+i);const day=d.toISOString().slice(0,10);return <section key={day}><h3>{day}</h3>{work.filter(({a})=>a.start<=day&&a.due>=day).map(({job,a})=><button key={job.id+a.id} onClick={()=>onOpen(job,'laboratory?activity='+encodeURIComponent(a.id))}><strong>{job.jobNumber}</strong><span>{a.title} · {a.sampleId}</span><small>{actor.employees.find(e=>e.id===a.owner)?.name||'Unassigned'} · Due {a.due}</small><small>{a.status}</small>{a.notes&&<small>{a.notes}</small>}</button>)}</section>;})}</div>}{!work.length&&<p>No activities in this view. New assignments will appear after the responsible manager saves the plan.</p>}{teamView&&<><h3>Jobs awaiting planning</h3>{jobs.filter(j=>actor.id==='MA001'?(!operationsFor(j).scopeConfirmedAt||operationsFor(j).activities.some(a=>!a.owner)):pendingActions(j,actor).some(m=>['scope','laboratory'].includes(m.id))).map(j=><button key={j.id} className="ops-task" onClick={()=>onOpen(j,operationsFor(j).scopeConfirmedAt?'laboratory':'scope')}>{j.jobNumber} · {j.clientName} — Confirm scope / assign work</button>)}</>}</section>;
}

